evidence.quote:
quietly forval i=1/91 {
	by PERMNO:gen LAG_VWRETD_`i'=vwretd[_n-`i']
}
egen FirmVolatility=rowsd(RET LAG_RET_1-LAG_RET_63)
egen MarketVolatility=rowsd(vwretd LAG_VWRETD_1-LAG_VWRETD_63)
quietly forval i=1/91 {
	by PERMNO:gen LEAD_RET_`i'=RET[_n+`i']
}
quietly forval i=1/91 {
	by PERMNO:gen LEAD_VWRETD_`i'=vwretd[_n+`i']
}
gen CAR_1_1=RET-vwretd
quietly forval i=1/1 {
	replace CAR_1_1=CAR_1_1+LAG_RET_`i'-LAG_VWRETD_`i'+LEAD_RET_`i'-LEAD_VWRETD_`i'
}
rename CAR_1_1 CAR
rangestat (cov) RET vwretd, interval(date -365 -60) by(PERMNO)
rangestat (variance) vwretd, interval(date -365 -60) by(PERMNO)
gen Beta=cov_x/vwretd_variance
duplicates drop CUSIP date, force
keep PERMNO date TICKER CUSIP PRC2 FirmVolatility MarketVolatility CAR Beta
save "CRSP_MERGED RETURNS.dta", replace 
